import{_ as e,o as i,c as a,ao as s}from"./chunks/framework.CWHsw1fv.js";const c=JSON.parse('{"title":"Working with other packages","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem.md","filePath":"ecosystem.md","lastUpdated":null}'),r={name:"ecosystem.md"};function n(l,t,o,h,d,p){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="Working-with-other-packages" tabindex="-1">Working with other packages <a class="header-anchor" href="#Working-with-other-packages" aria-label="Permalink to &quot;Working with other packages {#Working-with-other-packages}&quot;">​</a></h1><p>PureOSQP has <strong>no required dependencies</strong>. Capabilities appear as you load relevant packages via Julia&#39;s extension mechanism.</p><p>Two mechanisms are at work:</p><p><strong>Extensions</strong> are code that loads only when you load a trigger package. There are seven, listed below.</p><p><strong>Genericity</strong> allows the solver to handle any numeric or matrix type that behaves correctly. Precision types are handled this way, without needing extensions.</p><h2 id="Number-types" tabindex="-1">Number types <a class="header-anchor" href="#Number-types" aria-label="Permalink to &quot;Number types {#Number-types}&quot;">​</a></h2><p>The element type of your arrays determines the solver&#39;s precision. All types below were tested and show identical convergence behavior.</p><table tabindex="0"><thead><tr><th style="text-align:right;">type</th><th style="text-align:right;">package</th><th style="text-align:right;">digits</th><th style="text-align:right;">cost vs <code>Float64</code></th><th style="text-align:right;">note</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Float32</code></td><td style="text-align:right;">—</td><td style="text-align:right;">~7</td><td style="text-align:right;">—</td><td style="text-align:right;">works; halves memory</td></tr><tr><td style="text-align:right;"><code>Float64</code></td><td style="text-align:right;">—</td><td style="text-align:right;">~16</td><td style="text-align:right;">1×</td><td style="text-align:right;">the default</td></tr><tr><td style="text-align:right;"><code>Double64</code></td><td style="text-align:right;"><a href="https://github.com/JuliaMath/DoubleFloats.jl" target="_blank" rel="noreferrer">DoubleFloats.jl</a></td><td style="text-align:right;">~32</td><td style="text-align:right;">~22×</td><td style="text-align:right;">best for extra precision</td></tr><tr><td style="text-align:right;"><code>Float128</code></td><td style="text-align:right;"><a href="https://github.com/JuliaMath/Quadmath.jl" target="_blank" rel="noreferrer">Quadmath.jl</a></td><td style="text-align:right;">~34</td><td style="text-align:right;">~85×</td><td style="text-align:right;">software-emulated</td></tr><tr><td style="text-align:right;"><code>BigFloat</code></td><td style="text-align:right;">stdlib</td><td style="text-align:right;">tunable</td><td style="text-align:right;">~264×</td><td style="text-align:right;">arbitrary precision</td></tr></tbody></table><p><code>Double64</code> is roughly four times faster than <code>Float128</code> at the same precision.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PureOSQP, DoubleFloats</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(P), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(q), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(A), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(l), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(u))</span></span></code></pre></div><p><strong><code>Rational</code> does not work</strong>, and the reason is inherent rather than a gap here: exact rational arithmetic grows denominators without bound, and <code>Rational{Int}</code> overflows within a few iterations. <code>Rational{BigInt}</code> avoids the overflow at a cost that makes it impractical.</p><p><strong>More precision does not make an ill-conditioned problem converge faster.</strong> This is worth saying plainly because it is a natural thing to reach for. The iteration count is a property of the problem&#39;s geometry, not of the arithmetic: at every precision above, the same problem took the same 250 iterations. Extra precision lowers the floor on achievable accuracy; it does not speed the descent toward it. If a badly conditioned problem is stopping at <code>max_iter</code>, see <a href="/PureOSQP.jl/dev/benchmarks#Conditioning">Conditioning</a> — the lever there is structure, not bits.</p><h2 id="Matrix-and-operator-types" tabindex="-1">Matrix and operator types <a class="header-anchor" href="#Matrix-and-operator-types" aria-label="Permalink to &quot;Matrix and operator types {#Matrix-and-operator-types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">package</th><th style="text-align:right;">what it buys</th><th style="text-align:right;">how</th></tr></thead><tbody><tr><td style="text-align:right;"><code>LinearAlgebra</code> (stdlib)</td><td style="text-align:right;"><code>Diagonal</code>, <code>Bidiagonal</code>, <code>SymTridiagonal</code>, <code>Tridiagonal</code>, <code>Symmetric</code>, views</td><td style="text-align:right;">genericity, plus dedicated backends</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaSparse/SparseArrays.jl" target="_blank" rel="noreferrer">SparseArrays</a> (stdlib)</td><td style="text-align:right;">sparse <code>P</code> and <code>A</code>, walked by stored entry</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaLinearAlgebra/BandedMatrices.jl" target="_blank" rel="noreferrer">BandedMatrices.jl</a></td><td style="text-align:right;">bandwidth ≥ 2</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaLinearAlgebra/LinearMaps.jl" target="_blank" rel="noreferrer">LinearMaps.jl</a></td><td style="text-align:right;">an operator you can apply but not store</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaSmoothOptimizers/Krylov.jl" target="_blank" rel="noreferrer">Krylov.jl</a></td><td style="text-align:right;">the matrix-free backend, needed for any operator</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaSmoothOptimizers/LDLFactorizations.jl" target="_blank" rel="noreferrer">LDLFactorizations.jl</a></td><td style="text-align:right;">a pure-Julia sparse <code>LDLᵀ</code> instead of SuiteSparse</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaGPU/GPUArrays.jl" target="_blank" rel="noreferrer">GPUArraysCore.jl</a></td><td style="text-align:right;">GPU arrays, matrix-free only</td><td style="text-align:right;">extension</td></tr></tbody></table><p><a href="/PureOSQP.jl/dev/matrices#Which-representation,-and-why">Which representation, and why</a> helps you choose.</p><p>Two key extensions:</p><ul><li><p><strong>LDLFactorizations</strong>: Provides a pure-Julia sparse <code>LDLᵀ</code>, making the package compatible with <code>juliac --trim</code>.</p></li><li><p><strong>Krylov</strong>: Required for any operator that cannot be materialized.</p></li></ul><h2 id="Modelling-and-interfaces" tabindex="-1">Modelling and interfaces <a class="header-anchor" href="#Modelling-and-interfaces" aria-label="Permalink to &quot;Modelling and interfaces {#Modelling-and-interfaces}&quot;">​</a></h2><p><a href="https://github.com/jump-dev/MathOptInterface.jl" target="_blank" rel="noreferrer">MathOptInterface.jl</a> has an extension, so PureOSQP is usable as a JuMP solver:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JuMP, PureOSQP, MathOptInterface</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(PureOSQP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Optimizer)</span></span></code></pre></div><p>The wrapper passes <code>MOI.Test</code>, which is a far more thorough conformance suite than anything hand-written.</p><h2 id="Differentiating-a-solve" tabindex="-1">Differentiating a solve <a class="header-anchor" href="#Differentiating-a-solve" aria-label="Permalink to &quot;Differentiating a solve {#Differentiating-a-solve}&quot;">​</a></h2><p>There are two ways to differentiate: 2. <strong>Built-in:</strong> <a href="/PureOSQP.jl/dev/api#PureOSQP.adjoint_derivative"><code>adjoint_derivative</code></a> and <a href="/PureOSQP.jl/dev/api#PureOSQP.forward_derivative"><code>forward_derivative</code></a> differentiate the <em>solution</em> by implicitly differentiating the KKT conditions. This is efficient and works in one solve.</p><ol start="3"><li><strong>Through iterations:</strong> Using <code>ForwardDiff.Dual</code> numbers differentiates the entire optimization loop. This is better for sensitivity analysis but is much more expensive.</li></ol><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PureOSQP, ForwardDiff</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ForwardDiff</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">derivative</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P, q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t, A, l, u)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">obj_val, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Checked against central differences on a small QP: agreement to <code>5e-11</code>.</p><p><strong>Prefer the built-in one for anything real.</strong> Forward mode costs one solve per parameter, and <code>P</code> alone has <code>n²</code> of them; and it differentiates <code>x_N(θ)</code>, the iterate you stopped at, rather than <code>x*(θ)</code>, the solution. They converge to the same thing, but the implicit form gets there in one solve and does not depend on the path taken. ForwardDiff&#39;s value here is as an independent check on the implicit derivative — exact, with no finite-difference step to choose — which is what the package&#39;s own tests use it for.</p>`,27)])])}const k=e(r,[["render",n]]);export{c as __pageData,k as default};
